begin;select plan(10);select ok((select relrowsecurity from pg_class where oid='public.students'::regclass),'students RLS ativo');select ok((select relrowsecurity from pg_class where oid='public.grades'::regclass),'grades RLS ativo');select ok((select relrowsecurity from pg_class where oid='public.audit_logs'::regclass),'audit_logs RLS ativo');select ok(not has_table_privilege('anon','public.students','SELECT'),'anon não lê students');select ok(not has_table_privilege('authenticated','public.audit_logs','SELECT'),'authenticated não lê audit_logs');select ok(not has_function_privilege('anon','public.verify_student_login(text,text,inet)','EXECUTE'),'anon não executa login interno');select ok(not has_table_privilege('authenticated','public.students','UPDATE'),'authenticated não altera students diretamente');select ok(not has_table_privilege('authenticated','public.audit_logs','DELETE'),'authenticated não apaga auditoria');select ok(not has_table_privilege('authenticated','public.audit_logs','UPDATE'),'authenticated não altera auditoria');select ok((select count(*)=1 from pg_trigger where tgname='audit_no_update'),'trigger de imutabilidade da auditoria existe');select * from finish();rollback;